variants.css:
@font-face {
  font-family: "HarmonyOS Sans SC";
  font-style: normal;
  font-weight: 400;
  src: local("HarmonyOS Sans SC Regular"), local("HarmonyOS_Sans_SC_Regular"), local("HarmonyOS Sans SC");
}
@font-face {
  font-family: "HarmonyOS Sans SC";
  font-style: normal;
  font-weight: 600;
  src: local("HarmonyOS Sans SC Medium"), local("HarmonyOS_Sans_SC_Medium"), local("HarmonyOS Sans SC Bold"), local("HarmonyOS Sans SC");
}
@font-face {
  font-family: "HarmonyOS Sans SC";
  font-style: normal;
  font-weight: 700;
  src: local("HarmonyOS Sans SC Bold"), local("HarmonyOS_Sans_SC_Bold"), local("HarmonyOS Sans SC");
}
@font-face {
  font-family: "Maple Mono NF CN";
  font-style: normal;
  font-weight: 400;
  src: local("Maple Mono NF CN"), local("Maple Mono NF CN-Regular"), local("Maple Mono");
}
@font-face {
  font-family: "Maple Mono NF CN";
  font-style: normal;
  font-weight: 700;
  src: local("Maple Mono NF CN Bold"), local("Maple Mono NF CN-Bold"), local("Maple Mono Bold"), local("Maple Mono");
}

/* ================================================================
   TheBlue (Light Variant) CSS
   ================================================================ */

/* --- 1. Global Editor Typography & Selection --- */
:is([data-cap-content], .markdown-body, #editorarea-wrapper) {
  font-family: var(--mf-theme-font-editor-family) !important;
  line-height: var(--mf-theme-font-editor-line-height) !important;
  color: var(--mf-theme-text-primary) !important;
}

:is([data-cap-content], .markdown-body, #editorarea-wrapper) p {
  line-height: var(--mf-theme-font-editor-line-height) !important;
  margin-top: 0 !important;
  margin-bottom: 0.75rem !important;
  word-break: normal;
  word-wrap: break-word;
}

/* Caret color */
:where([data-cap-content], .markdown-body, #editorarea-wrapper) *:not(pre, pre *, .cm-editor, .cm-editor *, .capricorn-code-editor-shell, .capricorn-code-editor-shell *) {
  caret-color: #007aff !important;
}

/* Selection: 深蓝背景 + 纯白反色 (解决问题 4) */
::selection,
*::selection,
:is([data-cap-content], .markdown-body, #editorarea-wrapper) ::selection,
:is([data-cap-content], .markdown-body, #editorarea-wrapper) *::selection {
  background-color: #007aff !important;
  color: #ffffff !important;
  text-shadow: none !important;
}

/* Capricorn 自定义选区高亮 API */
::highlight(capricorn-selection) {
  background-color: #007aff !important;
  color: #ffffff !important;
}

/* --- 2. Headings (H1 ~ H6) --- */
:is([data-cap-content], .markdown-body) :is(
  h1, h2, h3, h4, h5, h6,
  .capricorn-markdown-heading-1,
  .capricorn-markdown-heading-2,
  .capricorn-markdown-heading-3,
  .capricorn-markdown-heading-4,
  .capricorn-markdown-heading-5,
  .capricorn-markdown-heading-6,
  [class*="markdown-heading-"]
) {
  position: relative !important;
  margin-top: 1.25rem !important;
  margin-bottom: 0.65rem !important;
  box-sizing: border-box !important;
  color: var(--mf-theme-text-primary) !important;
  cursor: text;
}

/* H1: Centered, no left bar, generous spacing */
:is([data-cap-content], .markdown-body) :is(h1, .capricorn-markdown-heading-1) {
  text-align: center !important;
  font-size: 1.75rem !important;
  line-height: 1.4 !important;
  font-weight: 700 !important;
  padding-bottom: 0.5rem !important;
  padding-left: 0 !important;
  border-left: none !important;
  border-bottom: none !important;
}

/* H2 ~ H6: Signature colored left bars (5px solid, 12px padding) */
:is([data-cap-content], .markdown-body) :is(
  h2, h3, h4, h5, h6,
  .capricorn-markdown-heading-2,
  .capricorn-markdown-heading-3,
  .capricorn-markdown-heading-4,
  .capricorn-markdown-heading-5,
  .capricorn-markdown-heading-6
) {
  display: block !important;
  border-left-width: 5px !important;
  border-left-style: solid !important;
  padding-left: 12px !important;
  padding-right: 0 !important;
  border-radius: 0 !important;
  border-top: none !important;
  border-right: none !important;
  border-bottom: none !important;
  background: transparent !important;
  outline: none !important;
  box-shadow: none !important;
}

/* H2: Black bar (1.625rem / 26px) */
:is([data-cap-content], .markdown-body) :is(h2, .capricorn-markdown-heading-2) {
  border-left-color: #000000 !important;
  font-size: 1.625rem !important;
  line-height: 1.4 !important;
  font-weight: 700 !important;
}

/* H3: Dark Blue #1565c0 (1.375rem / 22px) */
:is([data-cap-content], .markdown-body) :is(h3, .capricorn-markdown-heading-3) {
  border-left-color: #1565c0 !important;
  font-size: 1.375rem !important;
  line-height: 1.5 !important;
  font-weight: 700 !important;
}

/* H4: Core Blue #007aff (1.1875rem / 19px) */
:is([data-cap-content], .markdown-body) :is(h4, .capricorn-markdown-heading-4) {
  border-left-color: #007aff !important;
  font-size: 1.1875rem !important;
  line-height: 1.5 !important;
  font-weight: 600 !important;
}

/* H5: Light Blue #6ec0ff (1.0625rem / 17px) */
:is([data-cap-content], .markdown-body) :is(h5, .capricorn-markdown-heading-5) {
  border-left-color: #6ec0ff !important;
  font-size: 1.0625rem !important;
  line-height: 1.6 !important;
  font-weight: 600 !important;
}

/* H6: Pale Blue #b3e5fc (1rem / 16px) */
:is([data-cap-content], .markdown-body) :is(h6, .capricorn-markdown-heading-6) {
  border-left-color: #b3e5fc !important;
  font-size: 1rem !important;
  line-height: 1.6 !important;
  font-weight: 600 !important;
}

/* 标题内的行内代码：跟随标题字号等比缩放 (0.85em) (解决问题 3) */
:is([data-cap-content], .markdown-body) :is(
  h1, h2, h3, h4, h5, h6,
  .capricorn-markdown-heading-1,
  .capricorn-markdown-heading-2,
  .capricorn-markdown-heading-3,
  .capricorn-markdown-heading-4,
  .capricorn-markdown-heading-5,
  .capricorn-markdown-heading-6,
  [class*="markdown-heading-"]
) :is(code, .capricorn-markdown-inline-code, span[class*="inline-code"]) {
  font-size: 0.85em !important;
  font-weight: inherit !important;
  line-height: inherit !important;
  padding: 0.12em 0.35em !important;
  margin: 0 0.25em !important;
  border-radius: 0.25em !important;
  vertical-align: 0.04em !important;
}

/* --- 3. Inline Code & Highlights (<mark>) --- */
/* Standalone inline code: soft blue background #eef7ff + high contrast #0062cc */
:is([data-cap-content], .markdown-body) code:not(pre code, .cm-editor code) {
  font-family: var(--mf-theme-font-code-family) !important;
  font-size: 0.92rem;
  color: #0062cc !important;
  background-color: #eef7ff !important;
  border: none !important;
  border-radius: 4px !important;
  padding: 2px 6px !important;
  margin: 0 3px !important;
  overflow-wrap: break-word !important;
  word-break: break-word !important;
}

/* Code inside pre/cm-editor: clear inline pill styles */
:is([data-cap-content], .markdown-body) :is(pre, .cm-editor) code {
  background: transparent !important;
  background-color: transparent !important;
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  border-radius: 0 !important;
  font-size: inherit !important;
  line-height: inherit !important;
  color: inherit !important;
}

/* <mark> highlight: warm light gold #fff176 */
:is([data-cap-content], .markdown-body) mark {
  background-color: #fff176 !important;
  color: inherit !important;
  border-radius: 2px !important;
  padding-block: 1px !important;
  padding-inline: 3px !important;
  margin-inline: 0 !important;
  display: inline !important;
  box-decoration-break: clone;
  -webkit-box-decoration-break: clone;
}

/* Seamless ribbon stitching for adjacent marks */
:is([data-cap-content], .markdown-body) mark + mark {
  border-top-left-radius: 0 !important;
  border-bottom-left-radius: 0 !important;
  padding-left: 0 !important;
}
:is([data-cap-content], .markdown-body) mark:has(+ mark) {
  border-top-right-radius: 0 !important;
  border-bottom-right-radius: 0 !important;
  padding-right: 0 !important;
}

/* Seamless blend of code inside mark and mark inside code */
:is([data-cap-content], .markdown-body) :is(code:not(pre code):has(mark), mark code:not(pre code), code:not(pre code) mark) {
  background-color: #fff176 !important;
  background: #fff176 !important;
  color: #0050b3 !important;
  border-radius: 0 !important;
  margin-inline: 0 !important;
  padding-inline: 2px !important;
  font-weight: 600 !important;
  box-shadow: none !important;
  border: none !important;
  display: inline !important;
}

/* Clean Capricorn markdown mark markers */
.capricorn-markdown-mark-marker {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}
.capricorn-markdown-mark-marker:not(.show) {
  display: none !important;
  visibility: hidden !important;
}
.capricorn-markdown-mark-marker.show {
  display: inline !important;
  color: #8c8c8c !important;
  font-size: 0.85em !important;
}

/* --- 4. Blockquotes (TheBlue Signature - Continuous Flow 解决问题 1) --- */
/* Standard blockquote & Capricorn blockquote */
:is([data-cap-content], .markdown-body) blockquote {
  position: relative !important;
  border-left: 4px solid #007aff !important;
  background-color: rgba(0, 122, 255, 0.08) !important;
  background-image: none !important;
  padding: 8px 16px !important;
  margin: 0.75rem 0 !important;
  border-radius: 0 6px 6px 0 !important;
  box-sizing: border-box !important;
  color: inherit !important;
}

:is([data-cap-content], .markdown-body) blockquote > p {
  margin-top: 0 !important;
  margin-bottom: 0.35rem !important;
}
:is([data-cap-content], .markdown-body) blockquote > p:last-child {
  margin-bottom: 0 !important;
}

/* Capricorn 所见即所得编辑器的多行与连续引用块适配 (消除段落间白隙，将单块内换行展示为连贯一体的块) */
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote),
[data-cap-content] .capricorn-markdown-quoted-block,
[data-cap-content] p.capricorn-markdown-quoted-block,
[data-cap-content] div.capricorn-markdown-quoted-block {
  background-color: rgba(0, 122, 255, 0.08) !important;
  background-image: repeating-linear-gradient(to right, #007aff 0, #007aff .25em, transparent .25em, transparent 1em) !important;
  background-repeat: no-repeat !important;
  background-size: var(--markdown-blockquote-indent, 1em) 100% !important;
  border-left: none !important;
  padding-inline-start: calc(var(--markdown-blockquote-indent, 1em) + 4px) !important;
  padding-inline-end: 16px !important;
  box-sizing: border-box !important;
  color: inherit !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  padding-top: 3px !important;
  padding-bottom: 3px !important;
  border-radius: 0 !important;
}

/* 引用块连续段落：首行加外边距与右上圆角 */
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block)[data-markdown-blockquote-first="true"],
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote):not(blockquote + blockquote):not(.capricorn-markdown-quoted-block + blockquote):not([data-markdown-blockquote-first]),
[data-cap-content] .capricorn-markdown-quoted-block:not(.capricorn-markdown-quoted-block + .capricorn-markdown-quoted-block):not(blockquote + .capricorn-markdown-quoted-block):not([data-markdown-blockquote-first]) {
  margin-top: 0.75rem !important;
  padding-top: 8px !important;
  border-top-right-radius: 6px !important;
}

/* 引用块连续段落：末行加下外边距与右下圆角 */
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block)[data-markdown-blockquote-last="true"],
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote):not(:has(+ blockquote)):not(:has(+ .capricorn-markdown-quoted-block)):not([data-markdown-blockquote-last]),
[data-cap-content] .capricorn-markdown-quoted-block:not(:has(+ .capricorn-markdown-quoted-block)):not(:has(+ blockquote)):not([data-markdown-blockquote-last]) {
  margin-bottom: 0.75rem !important;
  padding-bottom: 8px !important;
  border-bottom-right-radius: 6px !important;
}

/* 独立单行引用块（既首又末） */
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block)[data-markdown-blockquote-first="true"][data-markdown-blockquote-last="true"],
[data-cap-content] .capricorn-markdown-quoted-block:not(.capricorn-markdown-quoted-block + .capricorn-markdown-quoted-block):not(:has(+ .capricorn-markdown-quoted-block)):not(:has(+ blockquote)) {
  margin-top: 0.75rem !important;
  margin-bottom: 0.75rem !important;
  padding-top: 8px !important;
  padding-bottom: 8px !important;
  border-radius: 0 6px 6px 0 !important;
}

/* 消除引用块中空行产生的断裂空隙 */
[data-cap-content] blockquote:empty,
[data-cap-content] .capricorn-markdown-blockquote:empty,
[data-cap-content] .capricorn-markdown-quoted-block:is(:empty, :has(> br:only-child)) {
  min-height: 1.2em !important;
  padding-block: 2px !important;
  margin-block: 0 !important;
  border-radius: 0 !important;
}

/* 引用块内的列表边距融合 */
[data-cap-content] .capricorn-markdown-list-item.capricorn-markdown-quoted-block {
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  padding-top: 2px !important;
  padding-bottom: 2px !important;
  padding-left: calc(var(--markdown-blockquote-indent, 1em) + .25em + var(--markdown-list-indent, 0em)) !important;
}
:is([data-cap-content], .markdown-body) blockquote > :is(ul, ol) {
  margin-top: 0.25rem !important;
  margin-bottom: 0.25rem !important;
  padding-left: 1.5rem !important;
}
:is([data-cap-content], .markdown-body) blockquote > :is(ul, ol) > li {
  margin-top: 0 !important;
}

/* 多层级嵌套引用块：渐进加深蓝底
   1. 标准 DOM 嵌套引用块（如 HTML 导出、打印等场景） */
:is([data-cap-content], .markdown-body) blockquote blockquote {
  background-color: rgba(0, 122, 255, 0.16) !important;
}
:is([data-cap-content], .markdown-body) blockquote blockquote blockquote {
  background-color: rgba(0, 122, 255, 0.25) !important;
}
:is([data-cap-content], .markdown-body) blockquote blockquote blockquote blockquote {
  background-color: rgba(0, 122, 255, 0.35) !important;
}

/* 2. Capricorn 扁平化多级引用块阶梯背景
   （外层保持浅色，仅在各级竖线内侧加深，彻底解决深色蔓延到左侧竖线之外的问题） */
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block):is(
  [data-markdown-depth="2"],
  [data-markdown-blockquote-depth="2"],
  [style*="--markdown-blockquote-depth: 2"],
  [style*="--markdown-depth: 2"]
) {
  background-color: transparent !important;
  background-image: 
    repeating-linear-gradient(to right, #007aff 0, #007aff .25em, transparent .25em, transparent 1em),
    linear-gradient(to right, rgba(0, 122, 255, 0.08) 0, rgba(0, 122, 255, 0.08) 1em, rgba(0, 122, 255, 0.16) 1em, rgba(0, 122, 255, 0.16) 100%) !important;
  background-size: var(--markdown-blockquote-indent, 2em) 100%, 100% 100% !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position: 0 0, 0 0 !important;
}

[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block):is(
  [data-markdown-depth="3"],
  [data-markdown-blockquote-depth="3"],
  [style*="--markdown-blockquote-depth: 3"],
  [style*="--markdown-depth: 3"]
) {
  background-color: transparent !important;
  background-image: 
    repeating-linear-gradient(to right, #007aff 0, #007aff .25em, transparent .25em, transparent 1em),
    linear-gradient(to right, rgba(0, 122, 255, 0.08) 0, rgba(0, 122, 255, 0.08) 1em, rgba(0, 122, 255, 0.16) 1em, rgba(0, 122, 255, 0.16) 2em, rgba(0, 122, 255, 0.25) 2em, rgba(0, 122, 255, 0.25) 100%) !important;
  background-size: var(--markdown-blockquote-indent, 3em) 100%, 100% 100% !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position: 0 0, 0 0 !important;
}

[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block):is(
  [data-markdown-depth="4"],
  [data-markdown-blockquote-depth="4"],
  [style*="--markdown-blockquote-depth: 4"],
  [style*="--markdown-depth: 4"],
  [data-markdown-depth="5"],
  [data-markdown-blockquote-depth="5"],
  [style*="--markdown-blockquote-depth: 5"],
  [style*="--markdown-depth: 5"]
) {
  background-color: transparent !important;
  background-image: 
    repeating-linear-gradient(to right, #007aff 0, #007aff .25em, transparent .25em, transparent 1em),
    linear-gradient(to right, rgba(0, 122, 255, 0.08) 0, rgba(0, 122, 255, 0.08) 1em, rgba(0, 122, 255, 0.16) 1em, rgba(0, 122, 255, 0.16) 2em, rgba(0, 122, 255, 0.25) 2em, rgba(0, 122, 255, 0.25) 3em, rgba(0, 122, 255, 0.35) 3em, rgba(0, 122, 255, 0.35) 100%) !important;
  background-size: var(--markdown-blockquote-indent, 4em) 100%, 100% 100% !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position: 0 0, 0 0 !important;
}

/* 引用块内部行内代码：纯白微胶囊 + 细蓝边框 */
:is([data-cap-content], .markdown-body) :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block) code:not(pre code) {
  background-color: #ffffff !important;
  border: 1px solid rgba(0, 122, 255, 0.22) !important;
  box-shadow: 0 1px 2px rgba(0, 122, 255, 0.05) !important;
}

:is([data-cap-content], .markdown-body) :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block) mark code:not(pre code) {
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
}


/* 列表内嵌套引用块与 Alert 缩进对齐 (解决问题 1) */
:is([data-cap-content], .markdown-body) :is(li, .capricorn-markdown-list-item) :is(blockquote, [class*="alert"], [class*="callout"], .capricorn-markdown-blockquote) {
  margin-left: 0 !important;
  margin-right: 0 !important;
  width: auto !important;
}

/* Capricorn 列表内嵌套引用块与 Callout 缩进对齐与背景定位 (解决问题 1) */
[data-cap-content] .capricorn-markdown-block.capricorn-markdown-list-nested-block:is(.capricorn-markdown-quoted-block, [data-markdown-callout], .capricorn-markdown-blockquote) {
  margin-inline-start: calc(.25em + var(--cap-list-marker-width, 1.5em) + var(--cap-list-marker-gap, .5em) + var(--markdown-list-indent, 0em)) !important;
  width: auto !important;
}

[data-cap-content] .capricorn-markdown-quoted-block.capricorn-markdown-list-nested-block {
  padding-inline-start: calc(var(--markdown-blockquote-indent, 1em) + 4px) !important;
  background-position: 0 0 !important;
}


/* GitHub Callout / Alert 专用配色保护 (防止被通用引用块单色覆盖) */
[data-cap-content] [data-markdown-callout] {
  background-color: rgba(0, 122, 255, 0.06) !important;
  background-image: repeating-linear-gradient(to right, var(--cap-callout-color, #007aff) 0, var(--cap-callout-color, #007aff) .25em, transparent .25em, transparent 1em) !important;
}
[data-cap-content] [data-markdown-callout="TIP"] {
  background-color: rgba(46, 160, 67, 0.08) !important;
}
[data-cap-content] [data-markdown-callout="IMPORTANT"] {
  background-color: rgba(130, 80, 223, 0.08) !important;
}
[data-cap-content] [data-markdown-callout="WARNING"] {
  background-color: rgba(187, 128, 9, 0.08) !important;
}
[data-cap-content] [data-markdown-callout="CAUTION"] {
  background-color: rgba(207, 34, 46, 0.08) !important;
}

/* --- 5. Links --- */
:is([data-cap-content], .markdown-body) a {
  color: #6f42c1 !important;
  font-weight: inherit !important;
  padding: 0 2px !important;
  text-decoration: underline !important;
  cursor: pointer !important;
  overflow-wrap: break-word !important;
  word-break: break-word !important;
  transition: color 0.15s ease;
}

:is([data-cap-content], .markdown-body) a:hover {
  color: #007aff !important;
}

/* --- 6. Strikethrough, Underline & Inline Styling --- */
:is([data-cap-content], .markdown-body) :is(del, s) {
  padding: 1px 2px !important;
  color: var(--mf-theme-text-primary) !important;
  text-decoration-line: line-through !important;
  text-decoration-color: #007aff !important;
  text-decoration-thickness: 1.5px !important;
  text-decoration-skip-ink: none !important;
}

:is([data-cap-content], .markdown-body) u {
  border-bottom: 2px solid var(--mf-theme-text-primary) !important;
  text-decoration: none !important;
}

:is([data-cap-content], .markdown-body) strong {
  font-weight: 700 !important;
  color: var(--mf-theme-text-primary) !important;
}

/* --- 7. Horizontal Rule --- */
:is([data-cap-content], .markdown-body) hr {
  height: 0 !important;
  padding: 0 !important;
  margin: 2rem 0 !important;
  background-color: transparent !important;
  border: 0 none !important;
  border-top: 2px dashed #6ec0ff !important;
  overflow: hidden !important;
  box-sizing: content-box !important;
}

/* --- 8. Lists & Task Lists (解决问题 2：勾选显示删除线) --- */
:is([data-cap-content], .markdown-body) ul > li::marker {
  color: #007aff !important;
}

:is([data-cap-content], .markdown-body) :is(ul, ol) {
  padding-left: 2rem !important;
  margin-top: 0.5rem !important;
  margin-bottom: 0.75rem !important;
}

:is([data-cap-content], .markdown-body) li {
