  .capricorn-markdown-task-prefix *,
  input[type='checkbox'],
  .capricorn-markdown-task-checkbox
) {
  text-decoration: none !important;
}

/* 任务列表已完成项目：字体颜色变浅并显示删除线 (解决问题 2) */
:is([data-cap-content], .markdown-body) :is(
  li,
  .capricorn-markdown-list-item,
  [data-markdown-task="true"],
  .task-list-item,
  .task-list-done
):has(:is(input:checked, [checked], [aria-checked="true"], [data-checked="true"], [data-state="checked"], .capricorn-markdown-task-checkbox:checked)) {
  color: var(--mf-theme-text-secondary, #767676) !important;
}

/* 关键：穿透定位到任务内容容器及内部所有文字、行内代码与叶子节点，强制应用删除线 */
:is([data-cap-content], .markdown-body) :is(
  li,
  .capricorn-markdown-list-item,
  [data-markdown-task="true"],
  .task-list-item,
  .task-list-done
):has(:is(input:checked, [checked], [aria-checked="true"], [data-checked="true"], [data-state="checked"], .capricorn-markdown-task-checkbox:checked)) :is(
  .capricorn-markdown-list-content,
  .capricorn-markdown-list-content *,
