  text-decoration-color: var(--mf-theme-text-secondary, #767676) !important;
  text-decoration-thickness: 1.2px !important;
}

/* 兄弟选择器兜底：跟随在已勾选 checkbox 之后的所有内容元素 */
:is([data-cap-content], .markdown-body) :is(
  input:checked,
  .capricorn-markdown-task-checkbox:checked
) ~ * {
  text-decoration: line-through !important;
  text-decoration-color: var(--mf-theme-text-secondary, #767676) !important;
  text-decoration-thickness: 1.2px !important;
}

/* --- 9. Tables (遵循 MarkFlowy 原生简约卡片风格，无斑马纹，防滚动重排闪烁) --- */
:is([data-cap-content], .markdown-body) table {
  width: 100% !important;
  margin: 0.75rem 0 !important;
  border-collapse: collapse !important;
  background-color: var(--cap-surface, #ffffff) !important;
  border: 1px solid var(--mf-theme-border-default, #e0e0e0) !important;
  border-radius: var(--cap-radius-sm, 6px) !important;
  overflow: hidden !important;
}

:is([data-cap-content], .markdown-body) table :is(th, td) {
  padding: 6px 12px !important;
  text-align: left !important;
  vertical-align: top !important;
  border: 1px solid var(--cap-border-subtle, #eeeeee) !important;
  background-color: var(--cap-surface, #ffffff) !important;
}

:is([data-cap-content], .markdown-body) table thead th {
  font-weight: 600 !important;
