}

/* Capricorn 原生网格表格行与单元格核心适配 */
:is([data-cap-content], .markdown-body) .capricorn-markdown-table-row {
  background-color: var(--cap-surface, #ffffff) !important;
  border: 1px solid var(--cap-border-subtle, #eeeeee) !important;
  border-bottom: 0 !important;
  color: var(--mf-theme-text-primary, inherit) !important;
}

:is([data-cap-content], .markdown-body) .capricorn-markdown-table-row:is([data-markdown-group-last], [data-markdown-table-last], :last-of-type) {
  border-bottom: 1px solid var(--cap-border-subtle, #eeeeee) !important;
}

:is([data-cap-content], .markdown-body) .capricorn-markdown-table-row[data-markdown-table-header="true"] {
  background-color: var(--cap-surface-subtle, #f7f7f7) !important;
