}

:is([data-cap-content], .markdown-body) .cm-editor .cm-lineNumbers .cm-gutterElement {
  background-color: #2b2b2b !important;
  color: #787878 !important;
}

/* Code block selection: IntelliJ dark blue #264f78 with white text */
:is([data-cap-content], .markdown-body) :is(pre, .cm-editor, .capricorn-code-editor-shell) ::selection,
:is([data-cap-content], .markdown-body) .cm-editor .cm-selectionBackground,
:is([data-cap-content], .markdown-body) .cm-editor.cm-focused > .cm-scroller > .cm-selectionLayer .cm-selectionBackground {
  background-color: #264f78 !important;
  color: #ffffff !important;
  text-shadow: none !important;
}

/* IntelliJ Darcula syntax tokens */
.tok-keyword, .tok-operator, .token.keyword, .token.operator, span[class*="tok-keyword"], span[class*="tok-operator"] { color: #CC7832 !important; }
.tok-className, .tok-typeName, .token.class-name, .token.function, span[class*="tok-className"], span[class*="tok-typeName"] { color: #FFD760 !important; }
.tok-string, .token.string, span[class*="tok-string"] { color: #6A8759 !important; }
.tok-number, .token.number, span[class*="tok-number"] { color: #6897BB !important; }
.tok-comment, .token.comment, span[class*="tok-comment"] { color: #808080 !important; font-style: italic !important; }
.tok-variableName, .tok-propertyName, .tok-attributeName, span[class*="tok-variableName"], span[class*="tok-propertyName"] { color: #9876AA !important; }
.tok-tagName, span[class*="tok-tagName"] { color: #E8BF6A !important; }
.tok-macroName, span[class*="tok-macroName"] { color: #BBB529 !important; }
.tok-punctuation, .token.punctuation { color: #A9B7C6 !important; }
.tok-invalid, .tok-deleted, .token.error { color: #BC3F3C !important; }
.tok-inserted, .token.inserted { color: #629755 !important; }

/* --- 12. 行间与行内公式美化 (Math Blocks - 支持 Capricorn MathJax SVG 与 KaTeX 全渲染器 - 解决问题 2) --- */
:is([data-cap-content], .markdown-body) :is(
  div[data-type="math-block"],
  .mf-live-preview-math,
  .capricorn-markdown-math-block,
  .mathjax-block,
  .capricorn-math-preview,
  .katex,
  mjx-container,
  mjx-container[display="true"],
  mjx-container[jax="SVG"]
) {
  color: var(--mf-theme-text-primary, #000000) !important;
  opacity: 1 !important;
}

:is([data-cap-content], .markdown-body) :is(
  div[data-type="math-block"],
  .mf-live-preview-math,
  .capricorn-markdown-math-block,
  .mathjax-block,
  .capricorn-math-preview,
  .katex,
  mjx-container
) svg {
  color: var(--mf-theme-text-primary, #000000) !important;
  fill: currentColor !important;
  stroke: currentColor !important;
  stroke-width: 0.35px !important;
}

/* 消除公式内部可能被外层继承的零散下划线/删除线 */
:is([data-cap-content], .markdown-body) :is(
  .capricorn-math-preview,
  .katex,
  mjx-container
) * {
  text-decoration: none !important;
}

/* 数学公式单线水平居中贯穿覆盖线 (解决问题 2：彻底解决 SVG 与 inline-block 公式无法被原生 text-decoration 穿透的问题) */
:is([data-cap-content], .markdown-body) :is(
  del, s, strike,
  li:has(:is(input:checked, [checked], [aria-checked="true"], [data-checked="true"], [data-state="checked"], .capricorn-markdown-task-checkbox:checked)),
  .capricorn-markdown-list-item:has(:is(input:checked, [checked], [aria-checked="true"], [data-checked="true"], [data-state="checked"], .capricorn-markdown-task-checkbox:checked)),
  [data-markdown-task="true"]:has(:is(input:checked, [checked], [aria-checked="true"], [data-checked="true"], [data-state="checked"], .capricorn-markdown-task-checkbox:checked))
) :is(
  .capricorn-math-preview,
  .capricorn-math-preview--inline,
  .capricorn-math-preview-svg,
  .katex,
  mjx-container,
  .capricorn-markdown-inline-math,
  .mf-live-preview-math
) {
  position: relative !important;
  display: inline-flex !important;
  vertical-align: middle !important;
  text-decoration: none !important;
}

:is([data-cap-content], .markdown-body) :is(
  del, s, strike,
  li:has(:is(input:checked, [checked], [aria-checked="true"], [data-checked="true"], [data-state="checked"], .capricorn-markdown-task-checkbox:checked)),
  .capricorn-markdown-list-item:has(:is(input:checked, [checked], [aria-checked="true"], [data-checked="true"], [data-state="checked"], .capricorn-markdown-task-checkbox:checked)),
  [data-markdown-task="true"]:has(:is(input:checked, [checked], [aria-checked="true"], [data-checked="true"], [data-state="checked"], .capricorn-markdown-task-checkbox:checked))
) :is(
  .capricorn-math-preview,
  .capricorn-math-preview--inline,
  .katex,
  mjx-container,
  .capricorn-markdown-inline-math,
  .mf-live-preview-math
)::after {
  content: '' !important;
  position: absolute !important;
  left: 0 !important;
  right: 0 !important;
  width: 100% !important;
  top: 50% !important;
  height: 1.5px !important;
  background-color: var(--mf-theme-text-secondary, #767676) !important;
  transform: translateY(-50%) !important;
  pointer-events: none !important;
  z-index: 10 !important;
  box-sizing: border-box !important;
}

/* del / s / strike 明确删除线中公式覆盖线颜色 */
:is([data-cap-content], .markdown-body) :is(del, s, strike) :is(
  .capricorn-math-preview,
  .capricorn-math-preview--inline,
  .katex,
  mjx-container,
  .capricorn-markdown-inline-math,
  .mf-live-preview-math
)::after {
  background-color: #007aff !important;
}

/* --- 13. Print & PDF Export (输出文档排版规范：完整对齐并强化 TheBlue Typora 原版规范) --- */
@media print {
  @page {
    margin: 20mm;
    size: auto;
  }
  html {
    font-size: 16px !important;
  }
  *, *::before, *::after {
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
  }

  /* 隐藏所有交互式界面、工具栏、滚动条与浮动辅助控件 */
  header, aside, nav, button, [role="toolbar"], .titlebar, .os-scrollbar,
  .capricorn-toolbar, .mf-site-header, .md-continue-help, .code-tooltip,
  .capricorn-block-actions, .capricorn-drag-handle {
    display: none !important;
  }

  /* 1. 标题防孤行保护（Orphan Control）：严禁标题孤留在页尾，确保与正文同页 */
  h1, h2, h3, h4, h5, h6,
  .capricorn-markdown-heading-1,
  .capricorn-markdown-heading-2,
  .capricorn-markdown-heading-3,
  .capricorn-markdown-heading-4,
  .capricorn-markdown-heading-5,
  .capricorn-markdown-heading-6,
  [class*="markdown-heading-"],
  :is([data-cap-content], .markdown-body) :is(
    h1, h2, h3, h4, h5, h6,
    .capricorn-markdown-heading-1,
    .capricorn-markdown-heading-2,
    .capricorn-markdown-heading-3,
    .capricorn-markdown-heading-4,
    .capricorn-markdown-heading-5,
    .capricorn-markdown-heading-6,
    [class*="markdown-heading-"]
  ) {
    display: block !important;
    position: relative !important;
    page-break-after: avoid !important;
    break-after: avoid !important;
    -webkit-box-decoration-break: clone !important;
    box-decoration-break: clone !important;
  }

  /* H1 顶级大标题在输出文档中保持干净居中或去侧条 */
  :is([data-cap-content], .markdown-body) :is(h1, .capricorn-markdown-heading-1) {
    border-left: none !important;
    padding-left: 0 !important;
  }

  /* 2. 块级组件防分页截断：严禁代码块、引用块、表格、图片、公式在分页处被腰斩 */
  pre, blockquote, table, figure, img,
  .md-fences,
  .cm-editor,
  .capricorn-code-editor-shell,
  .capricorn-code-editor-host,
  div[data-type="math-block"],
  .capricorn-markdown-math-block,
  .mathjax-block,
  mjx-container,
  :is([data-cap-content], .markdown-body) :is(
    pre, blockquote, table, figure, img,
    .cm-editor,
    .capricorn-code-editor-shell,
    .capricorn-code-editor-host,
    .capricorn-markdown-blockquote,
    .capricorn-markdown-quoted-block,
    div[data-type="math-block"],
    .capricorn-markdown-math-block,
    .mathjax-block,
    mjx-container
  ) {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
  }

  /* 3. 代码块打印平滑化与防白边接缝微调 */
  pre, .md-fences,
  .cm-editor,
  .capricorn-code-editor-shell,
  :is([data-cap-content], .markdown-body) :is(pre, .cm-editor, .capricorn-code-editor-shell) {
    -webkit-box-decoration-break: slice !important;
    box-decoration-break: slice !important;
    box-shadow: 0 0 0 1px #2b2b2b !important;
    filter: none !important;
    transform: none !important;
  }

  /* 4. 打印时图片的边框与阴影简化，保持纸张整洁 */
  img, :is([data-cap-content], .markdown-body) img {
    box-shadow: none !important;
    transform: none !important;
  }
}

