}

/* --- 4. Blockquotes (TheBlue Signature - Continuous Flow 解决问题 1) --- */
/* Standard blockquote & Capricorn blockquote */
:is([data-cap-content], .markdown-body) blockquote {
  position: relative !important;
  border-left: 4px solid #3794ff !important;
  background-color: rgba(55, 148, 255, 0.1) !important;
