  margin-bottom: 0 !important;
}

/* Capricorn 所见即所得编辑器的多行与连续引用块适配 (消除段落间白隙，将单块内换行展示为连贯一体的块) */
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote),
[data-cap-content] .capricorn-markdown-quoted-block,
[data-cap-content] p.capricorn-markdown-quoted-block,
