  padding-inline-end: 16px !important;
  box-sizing: border-box !important;
  color: inherit !important;
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  padding-top: 3px !important;
  padding-bottom: 3px !important;
  border-radius: 0 !important;
}

/* 引用块连续段落：首行加外边距与右上圆角 */
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block)[data-markdown-blockquote-first="true"],
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote):not(blockquote + blockquote):not(.capricorn-markdown-quoted-block + blockquote):not([data-markdown-blockquote-first]),
[data-cap-content] .capricorn-markdown-quoted-block:not(.capricorn-markdown-quoted-block + .capricorn-markdown-quoted-block):not(blockquote + .capricorn-markdown-quoted-block):not([data-markdown-blockquote-first]) {
  margin-top: 0.75rem !important;
  padding-top: 8px !important;
  border-top-right-radius: 6px !important;
}

/* 引用块连续段落：末行加下外边距与右下圆角 */
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block)[data-markdown-blockquote-last="true"],
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote):not(:has(+ blockquote)):not(:has(+ .capricorn-markdown-quoted-block)):not([data-markdown-blockquote-last]),
[data-cap-content] .capricorn-markdown-quoted-block:not(:has(+ .capricorn-markdown-quoted-block)):not(:has(+ blockquote)):not([data-markdown-blockquote-last]) {
  margin-bottom: 0.75rem !important;
  padding-bottom: 8px !important;
  border-bottom-right-radius: 6px !important;
}

/* 独立单行引用块（既首又末） */
[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block)[data-markdown-blockquote-first="true"][data-markdown-blockquote-last="true"],
[data-cap-content] .capricorn-markdown-quoted-block:not(.capricorn-markdown-quoted-block + .capricorn-markdown-quoted-block):not(:has(+ .capricorn-markdown-quoted-block)):not(:has(+ blockquote)) {
  margin-top: 0.75rem !important;
  margin-bottom: 0.75rem !important;
  padding-top: 8px !important;
  padding-bottom: 8px !important;
  border-radius: 0 6px 6px 0 !important;
}

/* 消除引用块中空行产生的断裂空隙 */
[data-cap-content] blockquote:empty,
[data-cap-content] .capricorn-markdown-blockquote:empty,
[data-cap-content] .capricorn-markdown-quoted-block:is(:empty, :has(> br:only-child)) {
  min-height: 1.2em !important;
  padding-block: 2px !important;
  margin-block: 0 !important;
  border-radius: 0 !important;
}

/* 引用块内的列表边距融合 */
[data-cap-content] .capricorn-markdown-list-item.capricorn-markdown-quoted-block {
  margin-top: 0 !important;
  margin-bottom: 0 !important;
  padding-top: 2px !important;
  padding-bottom: 2px !important;
  padding-left: calc(var(--markdown-blockquote-indent, 1em) + .25em + var(--markdown-list-indent, 0em)) !important;
}
:is([data-cap-content], .markdown-body) blockquote > :is(ul, ol) {
  margin-top: 0.25rem !important;
  margin-bottom: 0.25rem !important;
  padding-left: 1.5rem !important;
}
:is([data-cap-content], .markdown-body) blockquote > :is(ul, ol) > li {
