  background-size: var(--markdown-blockquote-indent, 3em) 100%, 100% 100% !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position: 0 0, 0 0 !important;
}

[data-cap-content] :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block):is(
