  background-size: var(--markdown-blockquote-indent, 4em) 100%, 100% 100% !important;
  background-repeat: no-repeat, no-repeat !important;
  background-position: 0 0, 0 0 !important;
}

/* 引用块内部行内代码 */
:is([data-cap-content], .markdown-body) :is(blockquote, .capricorn-markdown-blockquote, .capricorn-markdown-quoted-block) code:not(pre code) {
