/* 列表内嵌套引用块与 Alert 缩进对齐 (解决问题 1) */
:is([data-cap-content], .markdown-body) :is(li, .capricorn-markdown-list-item) :is(blockquote, [class*="alert"], [class*="callout"], .capricorn-markdown-blockquote) {
